DROP TABLE IF EXISTS `page_contents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `page_contents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `menu` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '협회업무',
  `page_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `browser_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_link` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci,
  `is_published` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `page_contents_slug_unique` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `page_contents` DISABLE KEYS */;
INSERT INTO `page_contents` (`id`, `slug`, `menu`, `page_title`, `browser_title`, `category`, `category_link`, `content`, `is_published`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'membership','협회업무','일반·특별회원 가입','일반·특별회원 가입 - 한국CM협회','협회업무','/cmak/business/membership','<div class=\"sub-content-card\">\r\n<h2 class=\"sub-content-title\">일반&middot;특별회원 가입 안내</h2>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">회원구분</h3>\r\n<div style=\"display: flex; gap: 16px; flex-wrap: wrap;\">\r\n<div style=\"flex: 1; min-width: 240px; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden;\">\r\n<div style=\"background: #0061c2; color: #fff; padding: 11px 16px; font-weight: bold; font-size: 15px;\">일반회원</div>\r\n<div style=\"padding: 16px; line-height: 1.75; color: #444; font-size: 14px;\">건설산업기본법 제2조 제8호 및 제9호의 규정에 의한 건설사업관리 업으로 영위하고자 하는 자</div>\r\n</div>\r\n<div style=\"flex: 1; min-width: 240px; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden;\">\r\n<div style=\"background: #3FA6B9; color: #fff; padding: 11px 16px; font-weight: bold; font-size: 15px;\">특별회원</div>\r\n<div style=\"padding: 16px; line-height: 1.75; color: #444; font-size: 14px;\">협회의 목적과 사업에 찬동하는 일반회원 이외의 자</div>\r\n</div>\r\n</div>\r\n<div style=\"margin-top: 14px;\"><a style=\"display: inline-block; padding: 8px 16px; background: #0061c2; color: #fff; border-radius: 4px; text-decoration: none; font-size: 13px; font-weight: 600;\" href=\"/cmak/intro/members\">회원현황 보기 &rsaquo;</a></div>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">입회절차</h3>\r\n<div style=\"display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 8px;\">\r\n<div style=\"flex: 1; min-width: 120px; text-align: center; padding: 16px 10px; background: #f6f9fc; border: 1px solid #dde3ed; border-radius: 8px;\">\r\n<div style=\"display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-bottom: 8px; background: #0061c2; color: #fff; border-radius: 50%; font-size: 13px; font-weight: bold;\">1</div>\r\n<div style=\"font-size: 14px; color: #333; font-weight: 600; line-height: 1.4;\">입회원서 작성&middot;제출</div>\r\n</div>\r\n<span style=\"color: #0061c2; font-weight: bold; font-size: 18px; line-height: 1;\">&rsaquo;</span>\r\n<div style=\"flex: 1; min-width: 120px; text-align: center; padding: 16px 10px; background: #f6f9fc; border: 1px solid #dde3ed; border-radius: 8px;\">\r\n<div style=\"display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-bottom: 8px; background: #0061c2; color: #fff; border-radius: 50%; font-size: 13px; font-weight: bold;\">2</div>\r\n<div style=\"font-size: 14px; color: #333; font-weight: 600; line-height: 1.4;\">입회원서 접수&middot;통보</div>\r\n</div>\r\n<span style=\"color: #0061c2; font-weight: bold; font-size: 18px; line-height: 1;\">&rsaquo;</span>\r\n<div style=\"flex: 1; min-width: 120px; text-align: center; padding: 16px 10px; background: #f6f9fc; border: 1px solid #dde3ed; border-radius: 8px;\">\r\n<div style=\"display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-bottom: 8px; background: #0061c2; color: #fff; border-radius: 50%; font-size: 13px; font-weight: bold;\">3</div>\r\n<div style=\"font-size: 14px; color: #333; font-weight: 600; line-height: 1.4;\">입&middot;연회비 납부</div>\r\n</div>\r\n<span style=\"color: #0061c2; font-weight: bold; font-size: 18px; line-height: 1;\">&rsaquo;</span>\r\n<div style=\"flex: 1; min-width: 120px; text-align: center; padding: 16px 10px; background: #f6f9fc; border: 1px solid #dde3ed; border-radius: 8px;\">\r\n<div style=\"display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-bottom: 8px; background: #0061c2; color: #fff; border-radius: 50%; font-size: 13px; font-weight: bold;\">4</div>\r\n<div style=\"font-size: 14px; color: #333; font-weight: 600; line-height: 1.4;\">회원증 교부</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">입회원서</h3>\r\n<div style=\"border: 1px solid #dde3ed; border-radius: 8px; padding: 24px; max-width: 640px; margin: 0 auto;\">\r\n<h4 style=\"text-align: center; font-size: 18px; color: #0061c2; margin-bottom: 18px;\">일반회원 입회원서</h4>\r\n<table style=\"width: 100%; border-collapse: collapse; font-size: 14px;\">\r\n<tbody>\r\n<tr>\r\n<th style=\"width: 18%; padding: 10px; border: 1px solid #e2e8f0; background: #f6f9fc; text-align: left; font-weight: 600;\">① 명칭</th>\r\n<td style=\"width: 32%; padding: 10px; border: 1px solid #e2e8f0;\">&nbsp;</td>\r\n<th style=\"width: 18%; padding: 10px; border: 1px solid #e2e8f0; background: #f6f9fc; text-align: left; font-weight: 600;\">② 전화번호</th>\r\n<td style=\"width: 32%; padding: 10px; border: 1px solid #e2e8f0;\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<th style=\"padding: 10px; border: 1px solid #e2e8f0; background: #f6f9fc; text-align: left; font-weight: 600;\">③ 페이지</th>\r\n<td style=\"padding: 10px; border: 1px solid #e2e8f0;\">&nbsp;</td>\r\n<th style=\"padding: 10px; border: 1px solid #e2e8f0; background: #f6f9fc; text-align: left; font-weight: 600;\">④ 팩스번호</th>\r\n<td style=\"padding: 10px; border: 1px solid #e2e8f0;\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<th style=\"padding: 10px; border: 1px solid #e2e8f0; background: #f6f9fc; text-align: left; font-weight: 600;\">⑤ 소재지</th>\r\n<td style=\"padding: 10px; border: 1px solid #e2e8f0;\" colspan=\"3\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<th style=\"padding: 10px; border: 1px solid #e2e8f0; background: #f6f9fc; text-align: left; font-weight: 600;\">⑥ 대표자</th>\r\n<td style=\"padding: 10px; border: 1px solid #e2e8f0;\">&nbsp;</td>\r\n<th style=\"padding: 10px; border: 1px solid #e2e8f0; background: #f6f9fc; text-align: left; font-weight: 600;\">⑦ 주민등록번호</th>\r\n<td style=\"padding: 10px; border: 1px solid #e2e8f0;\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<th style=\"padding: 10px; border: 1px solid #e2e8f0; background: #f6f9fc; text-align: left; font-weight: 600;\">⑧ 업종 등</th>\r\n<td style=\"padding: 10px; border: 1px solid #e2e8f0;\">&nbsp;</td>\r\n<th style=\"padding: 10px; border: 1px solid #e2e8f0; background: #f6f9fc; text-align: left; font-weight: 600;\">⑨ 면허등의 취득일</th>\r\n<td style=\"padding: 10px; border: 1px solid #e2e8f0;\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style=\"margin-top: 16px; font-size: 13px; color: #555; text-align: center;\">정관 제5조 및 제6조의 규정에 의하여 귀 협회의 회원이 되고자 입회원을 제출합니다.</p>\r\n<div style=\"margin-top: 18px; text-align: right; font-size: 14px; line-height: 2;\">20&nbsp;&nbsp;&nbsp;년&nbsp;&nbsp;&nbsp;월&nbsp;&nbsp;&nbsp;일<br>제출인명칭 : ________________<br>대표자 : ________________ (인)</div>\r\n<p style=\"margin-top: 18px; font-size: 17px; font-weight: bold; color: #333;\">한국CM협회장 귀하</p>\r\n</div>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">제출서류</h3>\r\n<ol style=\"padding-left: 22px; line-height: 2;\">\r\n<li>입회원서 1부</li>\r\n<li>업면허증&middot;신고필증&middot;엔지니어링활동주체 회원수첩 사본 1부</li>\r\n<li>법인등기부등본&middot;사업자등록증 사본 (개인의 경우에는 사업자등록증 사본 또는 주민등록등본) 1부</li>\r\n<li>재무제표 중 손익계산서 사본 1부</li>\r\n<li>대표자 이력서 1부</li>\r\n</ol>\r\n<div style=\"margin-top: 12px; padding: 12px 16px; background: #f6f9fc; border-radius: 6px; font-size: 13px;\"><strong>관련자료</strong> &nbsp; <a href=\"/cmak/legacy/upload/data/session.hwp\" target=\"_blank\" rel=\"noopener noreferrer\">입회원서</a> &nbsp;|&nbsp; <a href=\"/cmak/legacy/upload/data/guidebook.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">협회활동현황</a> &nbsp;|&nbsp; <a href=\"/cmak/legacy/upload/data/회비규정.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">회비규정</a> &nbsp;|&nbsp; <a href=\"/cmak/legacy/upload/data/2012_CMAK정관.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">정관</a> &nbsp;|&nbsp; <a href=\"/cmak/legacy/upload/data/CMAK2.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">입금통장사본 |&nbsp; </a><a href=\"/cmak/file/11/download\" target=\"_blank\" rel=\"noopener\">첨부파일 테스트</a></div>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">회비 부과기준</h3>\r\n<h4 style=\"margin-top: 10px; margin-bottom: 8px; color: #0061c2; font-size: 15px;\">■ 시공능력평가액 기준</h4>\r\n<ul style=\"padding-left: 22px; line-height: 2;\">\r\n<li>시공능력평가액이 5조원 이상인 경우 : 1,000만원</li>\r\n<li>시공능력평가액이 1조원 이상 5조원 미만인 경우 : 600만원</li>\r\n<li>시공능력평가액이 5천억원 이상 1조원 미만인 경우 : 500만원</li>\r\n<li>시공능력평가액이 1천억원 이상 5천억원 미만인 경우 : 400만원</li>\r\n<li>시공능력평가액이 1천억원 미만인 경우 : 300만원</li>\r\n</ul>\r\n<h4 style=\"margin-top: 20px; margin-bottom: 8px; color: #0061c2; font-size: 15px;\">■ 매출액 기준</h4>\r\n<ul style=\"padding-left: 22px; line-height: 2;\">\r\n<li>매출액이 1,000억원 이상인 경우 : 400만원</li>\r\n<li>매출액이 700억원 이상 1,000억원 미만인 경우 : 350만원</li>\r\n<li>매출액이 500억원 이상 700억원 미만인 경우 : 300만원</li>\r\n<li>매출액이 300억원 이상 500억원 미만인 경우 : 250만원</li>\r\n<li>매출액이 100억원 이상 300억원 미만인 경우 : 200만원</li>\r\n<li>매출액이 100억원 미만인 경우 : 150만원</li>\r\n</ul>\r\n<p style=\"color: #3fa6b9; font-weight: bold; margin-top: 8px;\">※ 시공능력평가액과 매출액은 부과기준일의 최근치로 하되, 시공능력평가액이나 매출액이 없는 경우에는 영업용자산평가액으로 함.</p>\r\n<h4 style=\"margin-top: 20px; margin-bottom: 8px; color: #0061c2; font-size: 15px;\">■ 특별회비</h4>\r\n<ul style=\"padding-left: 22px; line-height: 2;\">\r\n<li>법인은 입회비 100만원 연회비 100만원으로 하고,</li>\r\n<li>개인은 입회비 5만원 연회비 5만원으로 함.</li>\r\n</ul>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">입회금</h3>\r\n<p>&nbsp;&nbsp;◆ 연도별 건설사업관리업무위탁계약금액의 1,000분의 1에 해당하는 금액을 부과하며,<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;그 부과금액은 5,000만원을 초과하지 아니한다.</p>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">계좌번호</h3>\r\n<p>&nbsp;&nbsp;◆ 계좌번호 : KEB하나은행 182-910007-92604<br>&nbsp;&nbsp;◆ 예 금 주 : 한국건설관리협회</p>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">특별회원의 제한사항</h3>\r\n<ul style=\"padding-left: 22px; line-height: 2;\">\r\n<li>특별회원(대의원은 제외함)은 아래 항목의 권리를 갖지 못한다.</li>\r\n<li>정관 및 협회 제 규정에 의하여 선임되는 자의 선거권 및 피선거권.</li>\r\n<li>총회에 출석하여 발언하고 표결.</li>\r\n</ul>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">회원의 의무</h3>\r\n<ul style=\"padding-left: 22px; line-height: 2;\">\r\n<li>회원의 품위보전.</li>\r\n<li>정관 및 관련규정의 준수.</li>\r\n<li>회비납부.</li>\r\n<li>기타 이사회나 총회에서 결정된 사항의 준수.</li>\r\n</ul>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">회원의 혜택</h3>\r\n<ul style=\"padding-left: 22px; line-height: 2;\">\r\n<li>CM시장 진출기반 선점&middot;구축.(발주정보교환, 의견제시 등 참여 활동, 애로사항 공동 대응.)</li>\r\n<li>회원 상호간, 지역간 정보교환 및 협력활동 기회 확대로 업무영역 확대도모.</li>\r\n<li>정부의 CM시책 및 각종 정보선점으로 미래 예측 및 진로 모색.</li>\r\n<li>CM업체로서의 신뢰성 및 대외 이미지 제고.</li>\r\n<li>발주기관 PQ심사에 필요한 CM실적확인서 발급.</li>\r\n<li>CM Herald 정기구독 및 각종 정보 자료의 공유.</li>\r\n<li>CM Herald와 협회 사이트를 통한 홍보.</li>\r\n</ul>\r\n<p><a href=\"/cmak/file/11/download\" target=\"_blank\" rel=\"noopener\">첨부파일 테스트</a></p>\r\n</div>\r\n<div class=\"sub-info-box\" style=\"margin-top: 30px; background: #f0f4fa;\">관련문의운영지원본부 &nbsp;☎&nbsp; 070-7510-1226 / 02-585-7092</div>\r\n</div>',1,0,'2026-07-26 23:23:42','2026-07-29 16:09:45',NULL),(2,'certification','협회업무','CM능력평가공시','CM능력평가·공시 - 한국CM협회','협회업무','/cmak/business/certification','<div class=\"sub-content-card\">\n    <h2 class=\"sub-content-title\">건설사업관리(CM)능력평가공시</h2>\n    <div class=\"sub-section\">\n        <p style=\"line-height:1.9;\">\n            우리 협회는 건설산업기본법 제23조의 2의 규정에 의거 매년 건설사업관리자의 건설사업관리능력을 평가·공시하고 있습니다.\n        </p>\n        <p style=\"line-height:1.9;\">\n            이는 발주자가 적정하게 건설사업관리자를 선정할 수 있도록 정보를 제공하기 위한 것으로서 건설사업관리자로부터 건설사업관리실적 및 건설공사실적·엔지니어링실적·설계실적·감리실적과 CM관련인력보유현황·재무정보현황·신용평가현황등에 관한 서류를 제출받아 건설사업관리능력을 평가하여 공시하는 것입니다.\n        </p>\n        <p style=\"line-height:1.9;\">\n            신청기한은 매년 2월1일부터 2월15일까지 이며, 공시는 그해 8월31일부터 익년도 8월30일까지 입니다.\n        </p>\n        <p style=\"line-height:1.9;\">\n            우리 협회는 국토교통부장관으로부터 건설사업관리능력평가·공시를 위탁 받아 수행하고 있습니다.<br>\n            (국토교통부 고시 제2008-785, 2008.12.29)\n        </p>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 건설사업관리(CM)능력평가공시제도란?</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>발주자가 적정하게 건설사업관리자를 선정할 수 있도록 하기 위하여, 건설사업관리자의 신청이 있는 경우 국토교통부장관이 당해 건설사업관리자의 건설사업관리실적 및 재무상태등에 따라 건설사업관리능력을 평가하여 공시하는 것입니다. (건설산업기본법 제23조의2)</li>\n            <li>우리 (사)한국건설관리협회가 상기 건설사업관리 능력평가공시 업무를 국토교통부장관으로부터 위탁받아 수행하게 되었습니다. (국토교통부 고시 제2008-785, 2008.12.29)</li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 관련 법 조항</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li><a href=\"https://www.law.go.kr/법령/건설산업기본법/제23조의2\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0061c2; text-decoration:underline;\">건설산업기본법 제23조의2</a> (건설사업관리능력의 평가 및 공시)</li>\n            <li><a href=\"https://www.law.go.kr/법령/건설산업기본법/제91조\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0061c2; text-decoration:underline;\">건설산업기본법 제91조</a> (권한의 위임 위탁)</li>\n            <li><a href=\"https://www.law.go.kr/법령/건설산업기본법시행령/제87조\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0061c2; text-decoration:underline;\">건설산업기본법 시행령 제87조</a> (권한의 위탁)</li>\n            <li>건설산업기본법 시행규칙\n                <a href=\"https://www.law.go.kr/법령/건설산업기본법시행규칙/제25조의2\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0061c2; text-decoration:underline;\">제25조의2</a>,\n                <a href=\"https://www.law.go.kr/법령/건설산업기본법시행규칙/제25조의3\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0061c2; text-decoration:underline;\">25조의3</a>,\n                <a href=\"https://www.law.go.kr/법령/건설산업기본법시행규칙/제25조의4\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0061c2; text-decoration:underline;\">25조의4</a> (건설사업관리능력평가공시신청서 등의 제출, 건설사업관리관련 인력, 건설사업관리능력의 공시항목 및 공시시기 등)</li>\n            <li><a href=\"https://www.law.go.kr/법령/건설산업기본법시행규칙/제38조\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0061c2; text-decoration:underline;\">건설산업기본법 시행규칙 제38조제2항</a> (수수료)</li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 작성 요령 및 제출서류 양식</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>작성요령 &nbsp;\n                <a href=\"/cmak/legacy/upload/data/2026CM능력평가공시작성요령.zip\"><strong>작성요령</strong></a>\n                (2026년 CM능력평가·공시계획 설명회 책자)\n            </li>\n            <li>제출용 양식 &nbsp;\n                <a href=\"/cmak/legacy/upload/data/2026CM능력평가공시서식모음.zip\"><strong>서식모음</strong></a> &nbsp;|&nbsp;\n                <a href=\"/cmak/legacy/upload/data/2026CM서식(샘플).hwp\"><strong>샘플다운</strong></a>\n            </li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 평가·공시 수수료</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>◆ 수수료 : 540,000원</li>\n            <li>◆ 납부 방법 : 온라인 입금</li>\n            <li>◆ 납부계좌번호 : KEB하나은행 064-22-00743-0 (예금주 : 한국건설관리협회)</li>\n        </ul>\n        <div style=\"margin-top:14px; padding:12px 16px; background:#f6f9fc; border-radius:6px;\">\n            <strong>관련자료</strong> &nbsp;\n            <a href=\"/cmak/legacy/upload/data/CMAK1.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">사업자등록증</a> &nbsp;|&nbsp;\n            <a href=\"/cmak/legacy/upload/data/CMAK3.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">통장 사본</a> &nbsp;|&nbsp;\n            <a href=\"/cmak/legacy/upload/data/과오납금환불요청서.hwp\" target=\"_blank\" rel=\"noopener noreferrer\">과오납금환불요청서</a>\n        </div>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 공시 방법</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>◆ 공시 기간 : 매년 8월 31일부터 익년도 공시일전까지</li>\n            <li>◆ 공시 방법 : 국토교통부 건설산업지식정보시스템 &nbsp;\n                <a href=\"http://www.kiscon.net/pcm/pcm_info.asp\" target=\"_blank\" style=\"padding:4px 10px; background:#0061c2; color:white; border-radius:4px; text-decoration:none; font-size:13px;\">바로가기</a>\n            </li>\n        </ul>\n    </div>\n\n    <div class=\"sub-info-box\" style=\"margin-top:30px; background:#f0f4fa;\">\n        <dt>관련문의</dt>\n        <dd>사업지원본부 &nbsp;☎&nbsp; 02-585-4712~4</dd>\n    </div>\n</div>',1,1,'2026-07-26 23:23:42','2026-07-29 16:07:35',NULL),(3,'confirm','협회업무','CM실적 관리 및 확인서 발급','CM실적 관리 및 확인서 발급 - 한국CM협회','협회업무','/cmak/business/confirm','<div class=\"sub-content-card\">\r\n<h2 class=\"sub-content-title\">&middot; CM실적 관리 및 확인서 발급</h2>\r\n<p class=\"sub-content-desc\">우리 협회에서는 건설사업관리용역의 내용 및 실적에 대해서 발주자나 건설사업관리용역 수행자의 요청이 있는 경우 그의 내용 및 실적에 대한 확인서 발급업무를 하고 있습니다.</p>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\" style=\"color: #339999;\">- 관련규정</h3>\r\n<ul style=\"padding-left: 22px; line-height: 1.9;\">\r\n<li>건설산업기본법 제2조제8호 및 제9호(건설사업관리 및 시공책임형 건설사업관리 정의)</li>\r\n<li>건설산업기본법 제23조의2(건설사업관리능력의 평가 및 공시)</li>\r\n<li>건설기술진흥법 제39조(건설사업관리 등의 시행)</li>\r\n<li>국토교통부장관의 위탁업무 수행기관 등 지정\r\n<div style=\"padding-left: 10px; color: #666; font-size: 13px;\">(국토교통부 고시 제2014-445호, 2014.7.17 / 제2008-785호, 2008.12.29.)</div>\r\n</li>\r\n</ul>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">1. CM용역수행실적확인서 발급 절차</h3>\r\n<div style=\"display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin: 20px 0;\">\r\n<div style=\"flex: 1; min-width: 130px; text-align: center; padding: 16px 10px; background: #f6f9fc; border: 1px solid #dde3ed; border-radius: 8px;\">\r\n<div style=\"display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-bottom: 8px; background: #0061c2; color: #fff; border-radius: 50%; font-size: 13px; font-weight: bold;\">1</div>\r\n<div style=\"font-size: 13px; color: #333; font-weight: 600; line-height: 1.45;\">실적확인 신청서 FAX(02-585-2689) 제출</div>\r\n</div>\r\n<span style=\"color: #0061c2; font-weight: bold; font-size: 18px; line-height: 1;\">&rsaquo;</span>\r\n<div style=\"flex: 1; min-width: 130px; text-align: center; padding: 16px 10px; background: #f6f9fc; border: 1px solid #dde3ed; border-radius: 8px;\">\r\n<div style=\"display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-bottom: 8px; background: #0061c2; color: #fff; border-radius: 50%; font-size: 13px; font-weight: bold;\">2</div>\r\n<div style=\"font-size: 13px; color: #333; font-weight: 600; line-height: 1.45;\">수수료 온라인 입금 (KEB하나은행 064-22-00743-0)</div>\r\n</div>\r\n<span style=\"color: #0061c2; font-weight: bold; font-size: 18px; line-height: 1;\">&rsaquo;</span>\r\n<div style=\"flex: 1; min-width: 130px; text-align: center; padding: 16px 10px; background: #f6f9fc; border: 1px solid #dde3ed; border-radius: 8px;\">\r\n<div style=\"display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-bottom: 8px; background: #0061c2; color: #fff; border-radius: 50%; font-size: 13px; font-weight: bold;\">3</div>\r\n<div style=\"font-size: 13px; color: #333; font-weight: 600; line-height: 1.45;\">신청서 접수 및 심사</div>\r\n</div>\r\n<span style=\"color: #0061c2; font-weight: bold; font-size: 18px; line-height: 1;\">&rsaquo;</span>\r\n<div style=\"flex: 1; min-width: 130px; text-align: center; padding: 16px 10px; background: #f6f9fc; border: 1px solid #dde3ed; border-radius: 8px;\">\r\n<div style=\"display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-bottom: 8px; background: #0061c2; color: #fff; border-radius: 50%; font-size: 13px; font-weight: bold;\">4</div>\r\n<div style=\"font-size: 13px; color: #333; font-weight: 600; line-height: 1.45;\">확인서 발급</div>\r\n</div>\r\n</div>\r\n<div style=\"margin-top: 14px; display: flex; gap: 16px; flex-wrap: wrap; align-items: center; padding: 14px; background: #f6f9fc; border-radius: 6px;\"><a style=\"font-weight: 600;\" href=\"/cmak/legacy/upload/data/건설사업관리용역내용확인신청서.hwp\"> 📎 건설사업관리용역 실적확인 신청서 (HWP) </a> <a style=\"font-weight: 600; color: #0061c2;\" href=\"http://www.g4b.go.kr/svc/bcs/ptu/pul/Login.do\" target=\"_blank\" rel=\"noopener noreferrer\"> ▶ G4B 실적확인서 발급 </a> <a style=\"font-weight: 600;\" href=\"/cmak/legacy/html/business/온라인%20CM실적확인서%20사용자매뉴얼.pdf\" target=\"_blank\" rel=\"noopener noreferrer\"> 📄 G4B 실적확인서 매뉴얼 다운로드 </a></div>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">2. 작성요령</h3>\r\n<ol style=\"padding-left: 24px; line-height: 1.9;\">\r\n<li>용역개요는 개조식으로 주요사업개요 및 과업내용을 요약 기입.<br><span style=\"color: #666;\">&nbsp;&nbsp;&nbsp;※ 주상복합인 경우 주거 부문 면적과 주거외 부문 면적 기입.</span></li>\r\n<li>총 용역금액 및 기성액은 천원 단위로 기입.</li>\r\n<li>용역기간 및 계약일은 년월일 까지 기입.</li>\r\n</ol>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">3. 신규 실적확인 구비서류</h3>\r\n<ol style=\"padding-left: 24px; line-height: 1.9;\">\r\n<li>건설사업관리용역내용 확인 신청서 1부(법인도장 날인) Fax(02-585-2689) 제출.</li>\r\n<li>발주자 기성실적증명서 원본 1부(기성금액변경시 제출)</li>\r\n<li>사업개요를 확인 할 수 있는 서류 (건축허가서 또는 사업계획서)</li>\r\n<li>진행중인 사업이 완료되었을 경우<br><span style=\"color: #666;\">&nbsp;&nbsp;&nbsp;(건축물 대장 또는 사용승인서 1부, 준공필증(확인서) 1부, 기성실적 완납증명서 원본 1부)</span></li>\r\n</ol>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">4. 변경계약 실적확인 구비서류</h3>\r\n<ol style=\"padding-left: 24px; line-height: 1.9;\">\r\n<li>건설사업관리용역내용 확인 신청서 1부(법인도장 날인) Fax(02-585-2689) 제출</li>\r\n<li>변경계약서 제출(변경된 계약금액 통상회비 납부)</li>\r\n<li>변경 후 기성실적증명서 제출</li>\r\n</ol>\r\n</div>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">5. CM용역수행실적확인 수수료</h3>\r\n<ul style=\"padding-left: 22px; line-height: 1.9;\">\r\n<li>◆ 발급 수수료 : 50,000원</li>\r\n<li>◆ 납부계좌번호 : KEB하나은행 064-22-00743-0 (예금주 : 한국건설관리협회)</li>\r\n</ul>\r\n</div>\r\n<hr style=\"margin: 36px 0; border: none; border-top: 1px solid #e5e8ee;\">\r\n<h2 class=\"sub-content-title\">&middot; 실적확인서 온라인 발급서비스 이용시 유의사항</h2>\r\n<div class=\"sub-section\">\r\n<h3 class=\"sub-section-title\">G4B 회원가입 및 기관회원 가입</h3>\r\n<div style=\"margin-bottom: 14px;\"><a style=\"display: inline-block; padding: 10px 18px; background: #0061c2; color: white; border-radius: 4px; text-decoration: none; font-weight: 600;\" href=\"http://www.g4b.go.kr/svc/bcs/ptu/pul/Login.do\" target=\"_blank\" rel=\"noopener noreferrer\">G4B 바로가기</a> <a style=\"display: inline-block; margin-left: 6px; padding: 10px 16px; background: #f6f9fc; border: 1px solid #dde3ed; border-radius: 4px; text-decoration: none; color: #0061c2; font-weight: 600;\" href=\"/cmak/legacy/html/business/온라인%20CM실적확인서%20사용자매뉴얼.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">📄 G4B 실적확인서 매뉴얼</a></div>\r\n<ol style=\"padding-left: 24px; line-height: 2;\">\r\n<li>온라인 CM실적확인서를 신청하기 위해서는 G4B 회원가입 후 한국CM협회 기관회원 가입을 하여야 합니다.</li>\r\n<li>기존에 협회에 신고한 실적들 이외 신규실적과 변경사항들의 증빙서류를 제출하여야 합니다.<br><span style=\"color: #666;\">- 기존실적 변경 및 신규실적 포함시 해당됨.</span></li>\r\n<li>발급기관에서 한국CM협회를 선택하여 실적확인서 신청정보를 입력 후 신청합니다. 실적확인서를 신청하기 위해서는 법인공인인증서 인증을 받아야 합니다.</li>\r\n<li>실적확인서 신청시 발급수수료를 계좌이체로 납부하여야 합니다.</li>\r\n<li>신청하신 실적확인서는 실적확인서 발급조회 메뉴에 들어가시면 발급상태를 확인하실 수 있습니다.<br><span style=\"color: #666;\">- 발급수수료 입금확인시 출력가능상태로 변경됨</span></li>\r\n<li>발급이 완료된 실적확인서는 사용하시는 프린터를 이용하여 출력할 수 있습니다.</li>\r\n</ol>\r\n<p style=\"margin-top: 12px;\">※ 오프라인으로도 기존과 동일하게 발급 가능함.</p>\r\n</div>\n\n<div class=\"sub-section\">\n<h3 class=\"sub-section-title\">온라인 신청 절차</h3>\n<ol style=\"padding-left: 24px; line-height: 2;\">\n<li><strong>G4B 회원가입</strong><br>\n<a href=\"http://www.g4b.go.kr\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0061c2; font-weight:600;\">G4B 기업지원플러스(www.g4b.go.kr)</a> 접속 후 우측 상단 &quot;회원가입&quot; 버튼을 클릭합니다.</li>\n<li><strong>실적신고 신청</strong><br>\n로그인 &gt; 상단메뉴 &quot;시험&middot;인증&middot;실적&quot; &gt; 실적 &gt; 좌측메뉴 &quot;실적신고신청&quot; &gt; 한국CM협회 건설사업관리용역 실적 신고</li>\n<li><strong>실적확인서 발급 신청</strong><br>\n좌측 &quot;실적증명서발급신청&quot; 메뉴에서 한국CM협회 CM용역수행실적확인서 &quot;신청&quot;을 클릭합니다.</li>\n</ol>\n<p style=\"margin-top: 12px; color:#666;\">※ 자세한 내용은 온라인 CM실적확인서 사용자매뉴얼을 참조 바랍니다.</p>\n</div>\n\n<div class=\"sub-section\">\n<h3 class=\"sub-section-title\">CM 실적신고 안내사항</h3>\n<ul style=\"padding-left: 24px; line-height: 2;\">\n<li>협회에 기존 신고하신 CM실적은 협회 실적 담당자(<strong>02-585-4712 / 070-7510-1226~7</strong>)에게 연락주시면 업데이트해 드립니다.</li>\n<li>공공공사의 경우 발주자 CM용역 계약통보건에 한하여 신규 실적신고가 가능합니다.</li>\n<li>민간공사의 경우는 CM능력평가공시에서 CM실적으로 확정된 실적만 발급이 가능합니다.</li>\n</ul>\n</div>\n\n<div class=\"sub-section\">\n<h3 class=\"sub-section-title\">법인공인인증서 및 이용시간</h3>\n<ul style=\"padding-left: 24px; line-height: 2;\">\n<li>실적확인서를 신청한 기업고객이 확인서를 온라인 출력하기 위해서는 법인공인인증서를 이용한 신청자 확인절차가 필요합니다.</li>\n<li>실적확인서를 신청한 기업회원 이외에 <strong>제3자가 확인서를 열람하거나 출력할 수 없으므로</strong> 유의하시기 바랍니다.</li>\n<li>법인공인인증서는 금융기관 또는 공인인증서 발급기관을 통해 발급받으실 수 있습니다.</li>\n<li>온라인 CM 실적확인서 발급 이용시간은 <strong>08:30 ~ 18:00</strong> 까지 가능합니다.<br><span style=\"color:#666;\">(※ 단 토요일, 일요일, 공휴일은 서비스 제한이 있습니다.)</span></li>\n</ul>\n</div>\r\n<div class=\"sub-info-box\" style=\"margin-top: 30px; background: #f0f4fa;\">관련문의사업지원본부 &nbsp;☎&nbsp; 02-585-4712~4</div>\r\n</div>',1,2,'2026-07-26 23:23:42','2026-07-28 17:21:40',NULL),(4,'inspection','협회업무','건설사업관리사자격검정','건설사업관리사자격검정 - 한국CM협회','협회업무','/cmak/business/inspection','<div class=\"sub-content-card\">\n    {{-- 자격검정 운영 취지 및 안내 --}}\n    <div style=\"margin-bottom:24px; padding:18px 20px; background:#FBFBF3; border:1px solid #D8D5BB; border-radius:6px;\">\n        <p style=\"margin:0 0 10px 0; line-height:1.8;\">\n            우리 협회는 건설사업관리관련 인력의 적정한 자격제도 확립과 건설사업관리사의 자질 및 사회적\n            지위 향상을 도모하고 나아가 건설산업의 발전에 기여하기 위하여 건설사업관리사자격검정을\n            시행하고 있습니다.\n        </p>\n        <p style=\"margin:0; line-height:1.8; color:#0061c2;\">\n            본 자격은 자격기본법 제17조의 규정에 의한 민간자격으로, 국가로부터 인정받은 공인자격은 아닙니다.<br>\n            <strong>등록번호 : 2008-0397</strong>\n        </p>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 시험과목</h2>\n    <div class=\"sub-section\">\n        <table class=\"sub-table\" style=\"text-align:center;\">\n            <thead>\n                <tr style=\"background:#EDEFDE;\">\n                    <th style=\"width:100px;\">구분</th>\n                    <th>시험과목</th>\n                    <th>비고</th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr>\n                    <td rowspan=\"4\" style=\"background:#EDEFDE; font-weight:bold; border-bottom:2px solid #bbb;\">1차<br>필기시험</td>\n                    <td style=\"text-align:left;\">건설사업관리 개론</td>\n                    <td rowspan=\"10\" style=\"text-align:left; vertical-align:middle;\">\n                        <strong>자격검정 면제대상</strong><br>\n                        회장이 정하는 전문자격을 가진 자로서<br>\n                        3년 이상 실무경력이 있는 자의 경우<br><br>\n                        - 건설사업관리 개론<br>\n                        (필기시험 7개 과목 면제)<br>\n                        ※ 세부사항은 응시자격란 참조\n                    </td>\n                </tr>\n                <tr><td style=\"text-align:left;\">건설계약 및 클레임관리</td></tr>\n                <tr><td style=\"text-align:left;\">건설사업의사결정 및 위험관리</td></tr>\n                <tr><td style=\"text-align:left; border-bottom:2px solid #bbb;\">건설정보 및 문서관리</td></tr>\n                <tr>\n                    <td rowspan=\"4\" style=\"background:#EDEFDE; font-weight:bold; border-bottom:2px solid #bbb;\">2차<br>필기시험</td>\n                    <td style=\"text-align:left;\">경제성공학 및 사업비관리</td>\n                </tr>\n                <tr><td style=\"text-align:left;\">공정계획 및 관리</td></tr>\n                <tr><td style=\"text-align:left;\">품질관리 및 경영</td></tr>\n                <tr><td style=\"text-align:left; border-bottom:2px solid #bbb;\">건설안전 및 환경관리</td></tr>\n                <tr>\n                    <td rowspan=\"2\" style=\"background:#EDEFDE; font-weight:bold;\">면접시험</td>\n                    <td style=\"text-align:left;\">건설사업관리에 대한 전문성</td>\n                </tr>\n                <tr><td style=\"text-align:left;\">인성 및 표현능력</td></tr>\n            </tbody>\n        </table>\n        <p style=\"margin-top:10px;\">※ 시험과목의 세부 평가항목은 자격검정 시행공고문 참조</p>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 평가항목 및 참고서적</h2>\n    <div class=\"sub-section\">\n        <p style=\"line-height:1.9;\">\n            시험 평가항목과 참고서적은 매년 발표되는 <strong>건설사업관리사자격검정 시행계획 공고</strong>에 포함되어 있습니다.\n            응시 전 반드시 해당 공고문을 확인하시기 바랍니다.\n        </p>\n        <div style=\"margin-top:10px; padding:14px 16px; background:#f6f9fc; border:1px solid #dde3ed; border-radius:4px;\">\n            <a href=\"/cmak/legacy/upload/data/2026년도건설사업관리사자격검정시행계획공고.pdf\" target=\"_blank\" rel=\"noopener noreferrer\"\n               style=\"display:inline-block; padding:8px 16px; background:#0061c2; color:#fff; border-radius:4px; text-decoration:none; font-weight:600; font-size:13px;\">\n                📄 2026년도 자격검정 시행계획 공고 (시험 평가항목·참고서적 포함)\n            </a>\n        </div>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 검정기준·방법</h2>\n    <div class=\"sub-section\">\n        <table class=\"sub-table\" style=\"text-align:center;\">\n            <thead>\n                <tr style=\"background:#EDEFDE;\">\n                    <th colspan=\"2\">구분</th>\n                    <th>검정기준</th>\n                    <th>검정방법</th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr>\n                    <td rowspan=\"2\" style=\"background:#EDEFDE; font-weight:bold;\">필기<br>시험</td>\n                    <td style=\"background:#FBFBF3;\">1차과목</td>\n                    <td rowspan=\"2\" style=\"text-align:left;\">건설사업관리에 대한 전문지식과 실무경험에 따라 건설사업관리 업무를 행할 수 있는 능력을 평가</td>\n                    <td style=\"text-align:left;\">객관식(4지선다형 또는 5지선다형), OX문제</td>\n                </tr>\n                <tr>\n                    <td style=\"background:#FBFBF3;\">2차과목</td>\n                    <td style=\"text-align:left;\">객관식(4지선다형 또는 5지선다형), OX문제 또는 주관식(서술형 또는 단답형), 객관식/주관식 혼합형</td>\n                </tr>\n                <tr>\n                    <td colspan=\"2\" style=\"background:#EDEFDE; font-weight:bold;\">면접시험</td>\n                    <td style=\"text-align:left;\">표현능력·인성·전문성 등의 유무</td>\n                    <td style=\"text-align:left;\">구술형<br>※ 1차·2차 필기시험합격자에 한하여 실시.</td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 응시자격</h2>\n    <div class=\"sub-section\">\n        <table class=\"sub-table\">\n            <thead>\n                <tr style=\"background:#EDEFDE;\">\n                    <th style=\"width:110px; text-align:center;\">구분</th>\n                    <th>응시자격</th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr>\n                    <td style=\"background:#EDEFDE; text-align:center; font-weight:bold;\">건설사업관리사</td>\n                    <td>\n                        <ul style=\"padding-left:22px; line-height:1.9; margin:0;\">\n                            <li>관련분야의 석사학위 취득 후 2년 이상, 학사학위 취득 후 4년 이상, 전문대학 졸업 후 6년 이상, 고등학교 졸업 후 8년 이상 그 분야에 실무경력이 있는 자</li>\n                            <li>관련분야의 박사학위를 취득한 자</li>\n                            <li>관련분야의 기사 자격 취득 후 3년 이상, 산업기사자격 취득 후 4년 이상 그 분야에 실무경력이 있는 자</li>\n                            <li>건축사법에 따른 건축사 또는 기술사법에 따른 기술사</li>\n                        </ul>\n                    </td>\n                </tr>\n                <tr>\n                    <td style=\"background:#EDEFDE; text-align:center; font-weight:bold;\">자격검정<br>면제대상</td>\n                    <td>\n                        다음 각 목의 1에 해당하는 자격을 갖춘 자\n                        <ol style=\"padding-left:22px; line-height:1.9; margin:6px 0 0 0;\">\n                            <li>변호사법 제4조에 따라 자격을 취득한 변호사</li>\n                            <li>공인회계사법 제3조에 따라 자격을 취득한 공인회계사</li>\n                            <li>세무사법 제3조에 따라 자격을 취득한 세무사</li>\n                            <li>감정평가 및 감정평가사에 관한 법률 제11조에 따라 자격을 취득한 감정평가사</li>\n                            <li>변리사법 제3조에 따라 자격을 취득한 변리사</li>\n                            <li>법무사법 제4조에 따라 자격을 취득한 법무사</li>\n                            <li>행정사법 제5조에 따라 자격을 취득한 행정사</li>\n                            <li>공인노무사법 제3조에 따라 자격을 취득한 공인노무사</li>\n                        </ol>\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n        <div style=\"margin-top:12px; padding:14px; background:#FBFBF3; border:1px solid #C0C0C0; border-radius:4px;\">\n            <p style=\"margin:0 0 8px 0;\"><strong>※ 비고</strong></p>\n            <p style=\"margin:0 0 8px 0;\">1) 건설사업관리사는 단일등급이며 직무내용은 건설사업관리에 대한 지식을 활용하여 건설기술진흥법 시행령 별표1에 따른 각 전문분야별 직무와 건설지원(세무/회계/금융/노무/법무 등) 업무를 수행하는 것을 말한다.</p>\n            <p style=\"margin:0;\">2) 응시자격란의 \"관련분야\" 또는 \"그 분야\"란 건설사업관리관련 경력을 말하며, 자격검정 면제대상의 실무경력이란 각 호의 전문자격 분야의 경력을 말한다.</p>\n        </div>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 등록</h2>\n    <div class=\"sub-section\">\n        <div style=\"padding:14px; background:#FBFBF3; border:1px solid #C0C0C0; border-radius:4px;\">\n            <ul style=\"padding-left:22px; line-height:1.9; margin:0;\">\n                <li><strong>자격검정에 합격한 자</strong>는 합격한 날부터 <u><strong>90일 이내에 직무교육을 70시간 이상 이수</strong></u>하고 등록을 하여야 한다. 다만, 최종 합격일로부터 최근 3년 이내에 70시간 이상 직무교육을 이수한 자는 직무교육을 이수하지 않고 등록할 수 있다.</li>\n                <li><strong>직무교육 인정범위</strong>\n                    <ul style=\"padding-left:20px; margin-top:6px;\">\n                        <li><strong>교육기관 및 과정 :</strong> <u><span style=\"color:#FF0000;\"><strong>건설기술교육원과 한국기술사회</strong></span></u>의 건설사업관리전문교육 또는 건설사업관리전문가교육 (온라인교육 포함)</li>\n                        <li><strong>교육이수 인정기간 :</strong> 자격검정에 합격한 날부터 90일 이내 (또는 자격검정에 합격한 날 이전 최근 3년 이내)</li>\n                        <li><strong>교육이수 시간 :</strong> 70시간</li>\n                    </ul>\n                </li>\n            </ul>\n        </div>\n        <p style=\"margin-top:12px;\">※ <u style=\"color:#FF0000; font-weight:bold;\">해당 교육기관 외의 교육은 직무교육으로 인정되지 않습니다.</u> 자격시험 응시 전 응시자 본인의 응시자격을 반드시 확인하시기 바랍니다.</p>\n        <p>※ 자격검정 관련 세부사항은 건설사업관리사자격관리운영규정 및 동 규정 시행세칙을 참고하여 주시기 바랍니다.</p>\n\n        <div style=\"margin-top:14px; padding:12px 16px; background:#f6f9fc; border:1px solid #dde3ed; border-radius:4px;\">\n            <strong style=\"color:#0061c2;\">▶ 교육인정기관 바로가기</strong>\n            <div style=\"margin-top:8px; display:flex; gap:8px; flex-wrap:wrap;\">\n                <a href=\"https://www.kicte.or.kr/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"padding:6px 14px; background:#0061c2; color:#fff; border-radius:20px; text-decoration:none; font-size:13px;\">건설기술교육원</a>\n                <a href=\"https://www.kpea.or.kr/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"padding:6px 14px; background:#339999; color:#fff; border-radius:20px; text-decoration:none; font-size:13px;\">한국기술사회</a>\n            </div>\n        </div>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 관련 서식</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:2;\">\n            <li><a href=\"/cmak/legacy/upload/data/240604_건설사업관리사자격관리운영규정_최종.hwp\">건설사업관리사자격관리운영규정 (내려받기)</a></li>\n            <li><a href=\"/cmak/legacy/upload/data/240604_건설사업관리사자격관리운영규정시행세칙_최종.hwp\">건설사업관리사자격관리운영규정 시행세칙 (내려받기)</a></li>\n            <li><a href=\"/cmak/legacy/upload/data/자격검정원서.hwp\">자격검정 원서 (내려받기)</a></li>\n            <li><a href=\"/cmak/legacy/upload/data/2026년도건설사업관리사자격검정시행계획공고.pdf\" target=\"_blank\">2026년도 건설사업관리사자격검정 시행계획 공고 (내려받기)</a></li>\n            <li><a href=\"/cmak/legacy/upload/data/건설사업관리사자격검정수검포기원.hwp\">건설사업관리사자격검정 수검포기원 (내려받기)</a></li>\n            <li><a href=\"/cmak/legacy/upload/data/별지8-별지10응시자격확인서류제출.hwp\">[별지8-별지10] 응시자격 확인서류 제출 (내려받기)</a></li>\n            <li><a href=\"/cmak/legacy/upload/data/[별지11]건설사업관리사(갱신)등록신청서.hwp\">[별지11] 건설사업관리사(갱신) 등록신청서 (내려받기)</a></li>\n            <li><a href=\"/cmak/legacy/upload/data/별지4건설사업관리사자격증(자격수첩)재교부신청서.hwp\">[별지4] 건설사업관리사 자격증(자격수첩) 재교부신청서 (내려받기)</a></li>\n            <li><a href=\"/cmak/legacy/upload/data/직무교육연기신청서서식.hwp\">직무교육 연기신청서 서식 (내려받기)</a></li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 원서접수</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>접수기간내에 응시원서를 작성하여 접수처에 직접 제출(이메일 또는 우편 접수 가능)\n                <div style=\"padding-left:10px; color:#666;\">※ 우편으로 접수할 경우 등기로 우송하되 접수마감일자의 우체국 소인이 찍혀있는 것까지만 유효함.</div>\n            </li>\n            <li>접 수 처 : (06673) 서울특별시 서초구 서초대로 88, 유니온빌딩 4층.\n                <div style=\"padding-left:10px; color:#666;\">※ 지하철7호선 내방역 ④번출구에서 직진 100m.</div>\n            </li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 응시료</h2>\n    <div class=\"sub-section\">\n        <p><strong>총 비용 (자격증 발급 수수료 제외)</strong></p>\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>◆ 건설사업관리사 : 300,000원\n                <ul style=\"padding-left:20px;\">\n                    <li>1차 필기시험 : 160,000원</li>\n                    <li>2차 필기시험 : 140,000원</li>\n                </ul>\n            </li>\n            <li>◆ 자격검정 면제 : 160,000원\n                <ul style=\"padding-left:20px;\">\n                    <li>1차 필기시험 : 160,000원 (* 단, 제9조제3항 단서에 따른 필기시험의 경우: 250,000원)</li>\n                </ul>\n            </li>\n            <li>◆ 면접비의 경우, 면접시험 공고에 함께 게시될 예정.</li>\n            <li>◆ 자격발급비 : 합격자 최초발급에 한하여 무료.</li>\n            <li>◆ 납부계좌번호 : KEB하나은행 064-22-00743-0 (예금주 : 한국건설관리협회)</li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 재발급 안내</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>자격증 또는 자격수첩의 <strong>재교부</strong>를 받거나 자격을 <strong>갱신</strong>하고자 하는 경우 : <strong>각 20,000원</strong> (국문, 영문 별도)</li>\n            <li>재교부 신청 서식 : <a href=\"/cmak/legacy/upload/data/별지4건설사업관리사자격증(자격수첩)재교부신청서.hwp\" style=\"color:#0061c2;\">[별지4] 건설사업관리사 자격증(자격수첩) 재교부신청서</a></li>\n            <li>갱신 등록 서식 : <a href=\"/cmak/legacy/upload/data/[별지11]건설사업관리사(갱신)등록신청서.hwp\" style=\"color:#0061c2;\">[별지11] 건설사업관리사(갱신) 등록신청서</a></li>\n            <li>제출 및 문의 : 정책사업본부 <strong>☎ 070-7510-3090 / 070-7510-1227</strong>, 팩스 02-585-2689</li>\n            <li>납부계좌번호 : KEB하나은행 064-22-00743-0 (예금주 : 한국건설관리협회)</li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">· 접수취소·환불</h2>\n    <div class=\"sub-section\">\n        <h4 style=\"margin-top:10px;\"><strong>1. 접수취소 방법</strong></h4>\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>건설사업관리사자격검정응시포기원 및 본인 통장사본 제출</li>\n            <li>제출 및 문의 : 정책사업본부 <strong>☎ 070-7510-3090 / 070-7510-1227</strong>, <strong>팩스 02-585-2689</strong></li>\n        </ul>\n\n        <h4 style=\"margin-top:20px;\"><strong>2. 환불기준 (1차, 2차 시험 규정 동일)</strong></h4>\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>접수기간내 접수를 취소하는 경우 : 100% 환불 (마감일 18:00까지)</li>\n            <li>접수마감일 다음날로부터 시행일 5일전 18:00까지 취소하는 경우 : 50% 환불 (10원단위 절사)</li>\n        </ul>\n\n        <table class=\"sub-table\" style=\"text-align:center; margin-top:12px;\">\n            <thead>\n                <tr style=\"background:#EDEFDE;\">\n                    <th>구분</th>\n                    <th>접수기간 중</th>\n                    <th>접수기간 후</th>\n                    <th colspan=\"4\">시험시행 4일전</th>\n                    <th>시험당일</th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr>\n                    <td style=\"background:#EDEFDE; font-weight:bold;\">적용기간</td>\n                    <td>&nbsp;</td>\n                    <td>&nbsp;</td>\n                    <td>4일</td>\n                    <td>3일</td>\n                    <td>2일</td>\n                    <td>1일</td>\n                    <td>필기시험</td>\n                </tr>\n                <tr>\n                    <td style=\"background:#EDEFDE; font-weight:bold;\">환불적용률</td>\n                    <td>취소시<br>환불 100%</td>\n                    <td>취소시<br>환불 50%</td>\n                    <td colspan=\"5\" style=\"color:#FF0000; font-weight:bold;\">환불 및 취소 불가</td>\n                </tr>\n            </tbody>\n        </table>\n\n        <ul style=\"padding-left:22px; line-height:1.9; margin-top:12px;\">\n            <li>※ 취소 후 환불되기까지 <span style=\"color:#339999; font-weight:bold;\">약 2~7일 정도 소요</span>됩니다.</li>\n            <li>※ 접수마감일 다음날로부터 시행일 5일전 18:00까지 취소하는 경우 : 50% 환불 (10원단위 절사) 환불금액은 본인계좌로 입금되며 별도로 통보되지 않습니다.</li>\n            <li>※ 환불 및 취소불가 예외적용 : 직계가족 사망, 본인의 사고 또는 질병으로 입원한 자에 대해 검정수수료의 50% 환불</li>\n            <li>◆ 환불 및 취소불가 예외적용 대상 : 직계가족(본인 또는 배우자의 부모, 조부모, 형제, 자매, 배우자, 자녀에 한함) 사망자, 본인의 사고 또는 질병으로 입원한 자</li>\n            <li>◆ 기간 및 방법 : 수험자 시험일 기준 30일 이내, 건설사업관리사자격검정시험 응시포기원과 본인 통장사본, 입증서류를 첨부하여 협회 정책사업본부로 방문 또는 팩스신청</li>\n            <li>◆ 제출처 : 정책사업본부 <strong>☎ 070-7510-3090 / 070-7510-1227</strong>, <strong>팩스 02-585-2689</strong></li>\n            <li>◆ 입증서류</li>\n        </ul>\n\n        <table class=\"sub-table\" style=\"text-align:center; margin-top:12px;\">\n            <thead>\n                <tr style=\"background:#EDEFDE;\">\n                    <th>직계가족 등 사망</th>\n                    <th>본인 사고 및 질병에 의한 입원</th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr>\n                    <td>본인과의 가족관계 입증서류<br>(주민등록 등본, 가족관계증명서 등)</td>\n                    <td>입원을 입증하는 서류<br>(입원 확인서 등)</td>\n                </tr>\n                <tr>\n                    <td>사망 입증서류 (사망진단서 등)</td>\n                    <td>신분증</td>\n                </tr>\n                <tr>\n                    <td>신분증</td>\n                    <td>&nbsp;</td>\n                </tr>\n            </tbody>\n        </table>\n        <p style=\"margin-top:8px;\">※ 대리인 신청시 구비서류 : 대리인 및 수험자 본인의 신분증 첨부</p>\n    </div>\n\n    <div class=\"sub-info-box\" style=\"margin-top:30px; background:#f0f4fa;\">\n        <dt>관련문의</dt>\n        <dd>정책사업본부 &nbsp;☎&nbsp; 070-7510-3090 / 070-7510-1227</dd>\n    </div>\n</div>',1,3,'2026-07-26 23:23:42','2026-07-26 23:23:42',NULL),(5,'education','협회업무','CM교육','CM교육 - 한국CM협회','협회업무','/cmak/business/education','<div class=\"sub-content-card\">\n    <h2 class=\"sub-content-title\">CM교육</h2>\n\n    <div style=\"margin:18px 0 28px; padding:22px 24px; background:linear-gradient(135deg, #f4f9ff 0%, #fbfdff 100%); border:1px solid #d9e6f3; border-radius:8px;\">\n        <p style=\"margin:0 0 10px 0; font-size:16px; font-weight:700; color:#0061c2; line-height:1.6;\">\n            건설산업의 미래를 선도하는 CM 전문가 양성, 한국CM협회가 함께합니다.\n        </p>\n        <p style=\"margin:0 0 10px 0; line-height:1.8;\">\n            한국CM협회는 설립 이후, 건설사업관리(CM)의 체계적인 보급과 전문 인력 양성을 통해 국내 건설산업의 선진화 및 국제 경쟁력 강화에 앞장서 왔습니다.\n        </p>\n        <p style=\"margin:0; line-height:1.8;\">\n            현재 협회는 변화하는 교육 환경에 발맞추어, 정기 교육 과정 대신 <strong>회원사 맞춤형 교육 지원 체계</strong>를 통해 실무 중심의 핵심 역량 강화 서비스를 제공하고 있습니다.\n        </p>\n    </div>\n\n    <h2 class=\"sub-content-title\">1. 교육 목표</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li><strong>CM 역량 극대화</strong> : 건설사업의 기획부터 설계, 시공, 사후관리까지 전 과정에 걸친 과학적 관리 기법 보급을 통해 사업비 절감 및 품질 향상에 기여합니다.</li>\n            <li><strong>실무 전문가 양성</strong> : 이론과 사례를 결합한 심도 있는 교육으로 현업에 즉시 적용 가능한 최고급 CM 전문가를 육성합니다.</li>\n            <li><strong>산업 투명성 제고</strong> : 전문적인 관리 방법 보급을 통해 입찰 및 계약의 투명성과 객관성을 확보하고 공정한 경쟁 환경을 조성합니다.</li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">2. 주요 교육 서비스 (회원사 맞춤형 지원)</h2>\n    <div class=\"sub-section\">\n        <p style=\"line-height:1.8; margin-bottom:12px;\">\n            회원사가 주관하는 교육 과정의 내실을 기할 수 있도록 협회의 전문 인프라를 활용한 맞춤형 프로그램을 지원합니다.\n        </p>\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li><strong>회원사 맞춤형 출장 교육</strong> : 회원사가 필요로 하는 특정 주제나 실무 역량 강화를 위해 협회의 전문가 풀(Pool)을 활용하여 현장으로 직접 찾아가는 교육을 실시합니다.</li>\n            <li><strong>자체 교육 프로그램 지원</strong> : 회원사 내부에서 운영하는 교육 과정(예: 현장소장/단장 교육 등)에 협회의 검증된 교육 커리큘럼 및 전문 강사진을 일부 지원하여 교육 효과를 높여드립니다.</li>\n            <li><strong>최신 트렌드 및 사례 공유</strong> : 정부, 업계, 학계의 최고 실무 전문가로 구성된 강사 풀을 통해 최신 CM 트렌드와 성공 사례 중심의 지식을 전달합니다.</li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">3. 주요 지원 분야</h2>\n    <div class=\"sub-section\">\n        <ul style=\"padding-left:22px; line-height:1.9;\">\n            <li>CM 핵심 이론 및 실무 사례 분석</li>\n            <li>단계별(기획, 설계, 시공 등) 건설사업관리 기법</li>\n            <li>사업비 절감 및 공기 단축 방안</li>\n            <li>최신 건설 트렌드 및 CM 발주 트렌드 정보 공유</li>\n        </ul>\n    </div>\n\n    <h2 class=\"sub-content-title\">4. 교육 지원 문의</h2>\n    <div class=\"sub-section\">\n        <p style=\"line-height:1.8;\">\n            맞춤형 출장 교육 및 프로그램 지원에 관한 상세한 상담은 협회 사무국으로 문의해 주시기 바랍니다.\n        </p>\n    </div>\n\n    <div class=\"sub-info-box\" style=\"margin-top:18px; background:#f0f4fa;\">\n        <dt>관련문의</dt>\n        <dd>정책사업본부 &nbsp;☎&nbsp; 070-7510-3090 / 070-7510-1227</dd>\n    </div>\n\n    <div style=\"margin-top:30px; padding:22px 24px; background:#fbfbf3; border:1px solid #d8d5bb; border-radius:8px;\">\n        <h3 style=\"margin:0 0 14px 0; color:#0061c2; font-size:16px;\">[ 협회 교육 지원 역량 ]</h3>\n        <ul style=\"padding-left:18px; margin:0; line-height:1.9;\">\n            <li><strong>전문성</strong> : 1997년 이후 축적된 방대한 CM 교육 데이터와 커리큘럼 보유</li>\n            <li><strong>네트워크</strong> : 산·학·연을 아우르는 CM 분야 최고 수준의 전문가 네트워크 구축</li>\n            <li><strong>유연성</strong> : 기업별 특성에 맞춘 커스터마이징 교육 설계 가능</li>\n        </ul>\n    </div>\n</div>',1,4,'2026-07-26 23:23:42','2026-07-26 23:23:42',NULL),(6,'slogan','협회업무','건설사업관리(CM)표어','건설사업관리(CM)표어 - 한국CM협회','협회업무','/cmak/business/membership','<div class=\"sub-content-card\">\n<h2 class=\"sub-content-title\">건설사업관리(CM)표어</h2>\n<p class=\"sub-content-desc\">매년 선정되는 건설사업관리(CM) 표어 수상작입니다.</p>\n<div style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 20px; margin-top: 24px;\">\n<div style=\"border: 1px solid #e8ecf1; border-radius: 8px; overflow: hidden; text-align: center;\">\n<div style=\"background: #f0f4fa; padding: 10px; font-weight: bold; font-size: 15px; color: #064277;\">제20회 <span style=\"font-weight: normal; color: #4a6785;\">(2025년)</span></div>\n<div style=\"padding: 16px;\"><img style=\"max-width: 100%; height: auto; border-radius: 4px;\" src=\"/cmak/images/slogan/slogan_2025.jpg\" alt=\"제20회 건설사업관리(CM)표어 수상작 (2025년)\"></div>\n</div>\n<div style=\"border: 1px solid #e8ecf1; border-radius: 8px; overflow: hidden; text-align: center;\">\n<div style=\"background: #f0f4fa; padding: 10px; font-weight: bold; font-size: 15px; color: #064277;\">제19회 <span style=\"font-weight: normal; color: #4a6785;\">(2024년)</span></div>\n<div style=\"padding: 16px;\"><img style=\"max-width: 100%; height: auto; border-radius: 4px;\" src=\"/cmak/images/slogan/slogan_2024_2.jpg\" alt=\"제19회 건설사업관리(CM)표어 수상작 (2024년)\"></div>\n</div>\n<div style=\"border: 1px solid #e8ecf1; border-radius: 8px; overflow: hidden; text-align: center;\">\n<div style=\"background: #f0f4fa; padding: 10px; font-weight: bold; font-size: 15px; color: #064277;\">제18회 <span style=\"font-weight: normal; color: #4a6785;\">(2023년)</span></div>\n<div style=\"padding: 16px;\"><img style=\"max-width: 100%; height: auto; border-radius: 4px;\" src=\"/cmak/images/slogan/slogan_2024_1.jpg\" alt=\"제18회 건설사업관리(CM)표어 수상작 (2023년)\"></div>\n</div>\n<div style=\"border: 1px solid #e8ecf1; border-radius: 8px; overflow: hidden; text-align: center;\">\n<div style=\"background: #f0f4fa; padding: 10px; font-weight: bold; font-size: 15px; color: #064277;\">제17회 <span style=\"font-weight: normal; color: #4a6785;\">(2022년)</span></div>\n<div style=\"padding: 16px;\"><img style=\"max-width: 100%; height: auto; border-radius: 4px;\" src=\"/cmak/images/slogan/slogan_2023.jpg\" alt=\"제17회 건설사업관리(CM)표어 수상작 (2022년)\"></div>\n</div>\n<div style=\"border: 1px solid #e8ecf1; border-radius: 8px; overflow: hidden; text-align: center;\">\n<div style=\"background: #f0f4fa; padding: 10px; font-weight: bold; font-size: 15px; color: #064277;\">제16회 <span style=\"font-weight: normal; color: #4a6785;\">(2021년)</span></di