',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL),(9,19,'about_card',160,'Contact Us',NULL,'Get in touch with the CMAK secretariat in Seoul, Korea — we welcome inquiries from members and partners.',NULL,'06',NULL,'/cmak/eng/about/contact',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL),(10,19,'cmday_head',200,'Celebrating Construction Management Worldwide','Learn About CM Day','International CM Day brings together construction management professionals from around the globe to celebrate the value of CM and to share knowledge, achievements and best practices that shape the built environment.',NULL,'International CM Day',NULL,'/cmak/eng/cmday/introduction',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:37:37',NULL),(11,19,'cmday_stat',210,'29','Years of CMAK',NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-07-29 17:36:23','2026-07-29 17:37:38',NULL),(12,19,'cmday_stat',220,'20,000+','Members',NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL),(13,19,'cmday_stat',230,'9','Partner Countries',NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL),(14,19,'cmday_stat',240,'1997','Established',NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL),(15,19,'news_head',300,'What\'s Happening at CMAK',NULL,'Stay up to date with our latest publications, educations and events from CMAK and the global CM community.',NULL,'CMAK News',NULL,NULL,NULL,1,'2026-07-29 17:36:23','2026-07-29 17:37:39',NULL),(16,19,'news_card',310,'CM Herald Magazine and CMAK Annual Reports',NULL,NULL,'/cmak/images/eng/eng2.jpg','Publications','Latest Issue','/cmak/eng/news/publications',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:37:40',NULL),(17,19,'news_card',320,'Educations and Seminars for CM Professionals',NULL,NULL,'/cmak/images/eng/eng5.jpg','Education','Ongoing Programs','/cmak/eng/news/seminars',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL),(18,19,'news_card',330,'CMAK International Conferences and Forums',NULL,NULL,'/cmak/images/eng/eng4.jpg','Events','Annual','/cmak/eng/news/conferences',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL),(19,19,'quick_head',400,'Explore CMAK',NULL,NULL,NULL,'Quick Links',NULL,NULL,NULL,1,'2026-07-29 17:36:23','2026-07-29 17:37:40',NULL),(20,19,'quick_link',410,'IPMA Korea',NULL,'International project management certification',NULL,'globe',NULL,'/cmak/eng/ipma/about',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:37:41',NULL),(21,19,'quick_link',420,'Certification',NULL,'Become an internationally certified PM',NULL,'certificate',NULL,'/cmak/eng/ipma/certification',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL),(22,19,'quick_link',430,'Membership',NULL,'Join the CMAK community',NULL,'users',NULL,'/cmak/eng/membership',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL),(23,19,'quick_link',440,'Contact Us',NULL,'Visit or reach out to CMAK',NULL,'pin',NULL,'/cmak/eng/about/contact',NULL,1,'2026-07-29 17:36:23','2026-07-29 17:36:23',NULL);
